    """Basic CSS to XPath conversion for common cases"""
    if ' > ' in css_selector:
        parts = css_selector.split(' > ')
        return '//' + '/'.join(parts)
    if ' ' in css_selector:
        parts = css_selector.split(' ')
        return '//' + '//'.join(parts)
